package com.bank.ignore.repository;

import com.bank.ignore.model.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, String> {

    // BAD: UPPER() on the column defeats ix_email → sequential scan
    @Query(value = "SELECT * FROM accounts WHERE UPPER(email) = UPPER(:email)", nativeQuery = true)
    List<Account> searchByEmailBad(@Param("email") String email);

    // GOOD: matches expression index ix_email_lower → index scan
    @Query(value = "SELECT * FROM accounts WHERE LOWER(email) = LOWER(:email)", nativeQuery = true)
    List<Account> searchByEmailGood(@Param("email") String email);

    // Leading wildcard: normal index ignored, trigram index ix_name_trgm used
    @Query(value = "SELECT * FROM accounts WHERE holder_name ILIKE :pattern", nativeQuery = true)
    List<Account> searchByNameContains(@Param("pattern") String pattern);
}
