package com.bank.ignore.service;

import com.bank.ignore.model.Account;
import com.bank.ignore.repository.AccountRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class AccountSearchService {
    private static final Logger log = LoggerFactory.getLogger(AccountSearchService.class);
    private final AccountRepository repo;

    public AccountSearchService(AccountRepository repo) { this.repo = repo; }

    public List<Account> findByEmail(String email) {
        // We deliberately call the GOOD version that matches the expression index
        log.info("Searching by email using LOWER() expression index ix_email_lower");
        return repo.searchByEmailGood(email);
    }

    public List<Account> findByNameContains(String fragment) {
        log.info("Leading-wildcard name search '%{}%' uses trigram index ix_name_trgm", fragment);
        return repo.searchByNameContains("%" + fragment + "%");
    }
}
